window.AUTH=window.AUTH||{};window.AUTH["23-1002"]={"d":"23-1002","id":"2024/23-1002","n":"Hewitt v. United States","briefs":[{"k":"respondent","label":"Brief of respondent United States in support of petitioners","date":"2024-09-16","url":"https://www.supremecourt.gov/DocketPDF/23/23-1002/326089/20240916165721510_23-1002tsUnitedStates.pdf","side":"res","n":79},{"k":"petitioner","label":"Brief of petitioner Tony R. Hewitt","date":"2024-09-16","url":"https://www.supremecourt.gov/DocketPDF/23/23-1002/326082/20240916164041856_Hewitt%20merits%20brief%20FINAL.pdf","side":"pet","n":69},{"k":"petitioner","label":"Brief of petitioners Corey Deyon Duffey, et al.","date":"2024-09-16","url":"https://www.supremecourt.gov/DocketPDF/23/23-1002/326094/20240916170317980_Duffey%20Merits%20Brief%209-16-24%20Final.pdf","side":"pet","n":110},{"k":"reply","label":"Reply of petitioner Tony R. Hewitt","date":"2024-12-16","url":"https://www.supremecourt.gov/DocketPDF/23/23-1002/335314/20241216172844149_Hewitt%20Merits%20Reply%20Brief.pdf","side":"pet","n":39},{"k":"reply","label":"Reply of petitioners Corey Deyon Duffey and Jarvis Dupree Ross","date":"2024-12-16","url":"https://www.supremecourt.gov/DocketPDF/23/23-1002/335278/20241216152350770_Duffey%20Reply%20Brief%2012-16-24%20Final.pdf","side":"pet","n":50}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/606us1r61_2dp3.pdf","tr":true,"items":[{"t":"case","label":"Bartenwerfer v. Buckley","cite":"598 U.S. 69","y":2023,"id":"2022/21-908","sc":1,"sum":"Pursuant to §523(a)(2)(A) of the Bankruptcy Code, a debtor like Kate Bartenwerfer who is liable for her partner’s fraud cannot discharge that debt in bankruptcy, regardless of her own culpability.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23, 29"}},{"t":"case","label":"Borden v. United States","cite":"593 U.S. 420","y":2021,"id":"2020/19-5410","sc":1,"sum":"The decision of the Sixth Circuit—holding that an offense with a mental state of recklessness may qualify as a “violent felony” under the Armed Career Criminal Act’s elements clause, 18 U. S. C. §924(e)(2)(B)(i)—is reversed, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"29"}},{"t":"case","label":"Bravo-Fernandez v. United States","cite":"580 U.S. 5","y":2016,"id":"2016/15-537","sc":1,"op":4,"sum":"The Court decided that the Double Jeopardy Clause does not bar retrial when a jury returns an inconsistent verdict of conviction and acquittal and the convictions are later vacated for a completely separate legal error.","sumSrc":"Oyez","by":{"0":"27","3":"9, 10","4":"7, 8"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"sum":"The Court affirmed the lower court's decision and ruled for Gardner. The Court held that Section 1151 contains no language requiring proof of fault, and it rejected the Government's claims that the requirement was implicit in the language of the statute.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Brown v. United States","cite":"144 S. Ct. 1195","y":2024,"id":"2023/22-6389","sc":1,"sum":"For purposes of the Armed Career Criminal Act’s 15-year mandatory minimum sentence on certain defendants with three or more previous convictions, a state drug conviction counts as an ACCA predicate if it involved a drug on the federal schedules at the time of that offense.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23","3":"17"}},{"t":"case","label":"Burrell v. United States","cite":"384 F.3d 22","y":2004,"url":"https://www.courtlistener.com/c/F.3d/384/22/","op":1,"by":{"0":"27"}},{"t":"case","label":"Calderon v. Thompson","cite":"523 U.S. 538","y":1998,"id":"1997/97-215","sc":1,"sum":"The Court held that although it was consistent with the Antiterrorism and Effective Death Penalty Act of 1996, the recall was a grave abuse of discretion.","sumSrc":"Oyez","by":{"0":"24","1":"32"}},{"t":"case","label":"Carr v. United States","cite":"560 U.S. 438","y":2010,"id":"2009/08-1301","sc":1,"op":1,"sum":"The Court held that the Sex Offender and Registration Act does not apply to sex offenders' interstate travel that occurred before the Act's effective date.","sumSrc":"Oyez","by":{"0":"17","1":"27","2":"32","3":"12"}},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"op":9,"ar":6,"sum":"The Court held that Deal's second through sixth convictions in a single proceeding arose \"in the case of his second or subsequent conviction\" within the meaning of section 924(c)(1), finding that the statute was not ambiguous.","sumSrc":"Oyez","by":{"0":"5","1":"1, 2, 4, 29","2":"6, 41","3":"14"}},{"t":"case","label":"Dillon v. United States","cite":"560 U.S. 817","y":2010,"id":"2009/09-6338","sc":1,"sum":"The Court held that federal sentencing guidelines are binding when a district court imposes a new sentence under a revised guideline range.","sumSrc":"Oyez","by":{"0":"22","1":"9","2":"38, 40"}},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"op":4,"ar":3,"sum":"The Court held that criminals who had committed drug crimes before the passage of the Fair Sentencing Act of 2010 but were sentenced after its passage were entitled to the sentencing provisions laid out in the Act.","sumSrc":"Oyez","by":{"0":"14, 24, 26, 30","1":"8","2":"9, 10, 16, 39, 42, 45, 47, 49","3":"6, 16, 17"}},{"t":"case","label":"Gundy v. United States","cite":"588 U.S. 128","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17"}},{"t":"case","label":"Gwaltney of Smithfield, Ltd. v. Chesapeake Bay Foundation, Inc.","cite":"484 U.S. 49","y":1987,"id":"1987/86-473","sc":1,"op":1,"sum":"Section 505(a) of the Clean Water Act authorizes private citizens to commence a civil action for injunctive relief and/or the imposition of civil penalties in federal district court against any person \"alleged to be in violation\" of the conditions of a National Pollutant Discharge Elimination System (NPDES) permit. Between 1981 and 1984, petitioner repeatedly violated the conditions of its NPDES permit by exceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Lora v. United States","cite":"599 U.S. 453","y":2023,"id":"2022/22-49","sc":1,"sum":"The bar on imposition of concurrent sentences in 18 U. S. C. §924(c)(1)(D)(ii) does not apply to a sentence for a §924(j) conviction; a §924(j) sentence can run either concurrently with or consecutively to another sentence.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4"}},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"op":3,"ar":3,"sum":"Explaining that vacatur of a criminal sentence “wipe[s] the slate clean”.","sumSrc":"opinion","by":{"0":"13, 22, 23","1":"21, 33, 34","2":"3, 16-18, 29, 39, 46, 48","3":"7","4":"5, 10, 20"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"op":1,"sum":"A criminal defendant facing a mandatory minimum sentence is eligible for safety-valve relief under 18 U. S. C. §3553(f)(1) only if the defendant satisfies each of the provision’s three conditions.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"6, 20, 31","2":"8, 20, 28, 36","3":"20","4":"2, 3, 13, 20"}},{"t":"case","label":"Ramos v. Louisiana","cite":"590 U.S. 83","y":2020,"id":"2019/18-5924","sc":1,"sum":"The Court held that the Fourteenth Amendment fully incorporates the Sixth Amendment’s guarantee of a unanimous verdict against the states.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","2":"31"}},{"t":"case","label":"Smith v. Berryhill","cite":"587 U.S. 471","y":2019,"id":"2018/17-1606","sc":1,"sum":"A Social Security Administration Appeals Council dismissal on timeliness grounds of a request for review after a claimant has had an administrative law judge hearing on the merits qualifies as a “final decision . . . made after a hearing” for purposes of allowing judicial review under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"19","2":"32"}},{"t":"case","label":"Teague v. Lane","cite":"489 U.S. 288","y":1989,"id":"1988/87-5259","sc":1,"sum":"The judgment is affirmed. 820 F. 2d 832, affirmed. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, II, and III, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"United States v. Bethany","cite":"975 F.3d 642","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/975/642/","op":2,"by":{"0":"21"}},{"t":"case","label":"United States v. Cruz-Rivera","cite":"954 F.3d 410","y":2020,"url":"https://www.courtlistener.com/c/F.3d/954/410/","by":{"0":"25"}},{"t":"case","label":"United States v. Davis","cite":"588 U.S. 445","y":2019,"id":"2018/18-431","sc":1,"op":2,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"9","1":"5, 9","2":"6, 11"}},{"t":"case","label":"United States v. Eldridge","cite":"2 F.4th 27","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/2/27/","op":1,"by":{"0":"25"}},{"t":"case","label":"United States v. Frady","cite":"456 U.S. 152","y":1982,"id":"1981/80-1595","sc":1,"sum":"In 1963, respondent was convicted of first-degree murder and sentenced to death by a jury in the Federal District Court for the District of Columbia, which at that time had exclusive jurisdiction over local felonies committed in the District. The Court of Appeals for the District of Columbia Circuit, which then acted as the local appellate court, upheld the conviction but set aside the death sentence, and respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"United States v. Gomez","cite":"960 F.3d 173","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/960/173/","by":{"0":"25"}},{"t":"case","label":"United States v. Henry","cite":"983 F.3d 214","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/983/214/","by":{"0":"21","1":"7, 29, 32, 33, 34"}},{"t":"case","label":"United States v. Hodge","cite":"948 F.3d 160","y":2020,"url":"https://www.courtlistener.com/c/F.3d/948/160/","by":{"0":"25"}},{"t":"case","label":"United States v. Jefferson","cite":"989 F.3d 1173","y":2021,"url":"https://www.courtlistener.com/c/F.3d/989/1173/","by":{"0":"25"}},{"t":"case","label":"United States v. Jordan","cite":"952 F.3d 160","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/952/160/","by":{"0":"25"}},{"t":"case","label":"United States v. Merrell","cite":"37 F.4th 571","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/37/571/","op":1,"sum":"Holding that, under § 403(b), such an offender benefts from the Act at resentencing.","sumSrc":"opinion","by":{"0":"20","1":"33"}},{"t":"case","label":"United States v. Mitchell","cite":"38 F.4th 382","y":2022,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/38/382/","op":1,"by":{"0":"27","1":"8, 18, 31","2":"20, 24, 27","3":"9","4":"9"}},{"t":"case","label":"United States v. Reece","cite":"938 F.3d 630","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/938/630/","op":1,"by":{"0":"9"}},{"t":"case","label":"United States v. Richardson","cite":"948 F.3d 733","y":2020,"url":"https://www.courtlistener.com/c/F.3d/948/733/","by":{"0":"25","2":"46"}},{"t":"case","label":"United States v. Roberson","cite":"752 F.3d 517","y":2014,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/752/517/","op":1,"sum":"Upholding a conviction for failure to register as a sex offender even though the predicate sex offense was later vacated.","sumSrc":"opinion","by":{"0":"27","4":"6, 7"}},{"t":"case","label":"United States v. Smith","cite":"967 F.3d 1196","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/967/1196/","by":{"0":"5, 25"}},{"t":"case","label":"United States v. Snyder","cite":"235 F.3d 42","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/235/42/","by":{"0":"27","4":"6"}},{"t":"case","label":"United States v. Sparkman","cite":"973 F.3d 771","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/973/771/","by":{"0":"25"}},{"t":"case","label":"United States v. Smith","cite":"756 F.3d 1179","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/1179/","op":1,"sum":"Observing that it was “no fanciful possibility” that § 924(c) stacking would lead to “prison term[s] of many decades” that were “certain to outlast the defendant's life and the lives of every person now walking the planet”.","sumSrc":"opinion","by":{"0":"5"}},{"t":"case","label":"United States v. Uriarte","cite":"975 F.3d 596","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/975/596/","op":4,"ar":1,"by":{"0":"20, 21, 26, 31","1":"22, 23, 33, 34","2":"34, 48, 50","3":"11"}},{"t":"case","label":"United States v. Voris","cite":"964 F.3d 864","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/964/864/","by":{"0":"25"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"op":1,"sum":"It is the Attorney General who computes the amount of the § 3585(b) credit after the defendant has begun to serve his sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Whalen v. United States","cite":"445 U.S. 684","y":1980,"id":"1979/78-5471","sc":1,"op":2,"sum":"The Court of Appeals was mistaken in believing that Congress authorized consecutive sentences in the circumstances of this case, and that error denied petitioner his right to be deprived of liberty as punishment for criminal conduct only to the extent authorized by Congress.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Young v. United States","cite":"943 F.3d 460","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/943/460/","op":1,"by":{"0":"25","4":"14"}},{"t":"const","label":"Amendment V","clauses":[["double-jeopardy","Double Jeopardy Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 101-647","url":"https://www.govinfo.gov/link/statute/104/4789","by":{"0":"18"}},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"0":"2, 6, 14","2":"5"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1987","by":{"0":"22"}},{"t":"usc","label":"1 U.S.C. § 9","url":"https://www.law.cornell.edu/uscode/text/1/9","by":{"0":"30"}},{"t":"usc","label":"1 U.S.C. § 109","url":"https://www.law.cornell.edu/uscode/text/1/109","stext":{"head":"§109. Repeal of statutes as affecting existing liabilities","paras":[[0,"The repeal of any statute shall not have the effect to release or extinguish any penalty, forfeiture, or liability incurred under such statute, unless the repealing Act shall so expressly provide, and such statute shall be treated as still remaining in force for the purpose of sustaining any proper action or prosecution for the enforcement of such penalty, forfeiture, or liability. The expiration of a temporary statute shall not have the effect to release or extinguish any penalty, forfeiture, or liability incurred under such statute, unless the temporary statute shall so expressly provide, and such statute shall be treated as still remaining in force for the purpose of sustaining any proper action or prosecution for the enforcement of such penalty, forfeiture, or liability."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/109?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§109. Repeal of statutes as affecting existing liabilities","tname":"General Provisions","by":{"0":"15, 24","1":"2, 8","2":"9, 35, 44, 45","3":"6","4":"3, 22, 23"}},{"t":"usc","label":"10 U.S.C. § 863","url":"https://www.law.cornell.edu/uscode/text/10/863","subs":["(a)"],"by":{"0":"31"}},{"t":"usc","label":"10 U.S.C. § 950e","url":"https://www.law.cornell.edu/uscode/text/10/950e","by":{"0":"31"}},{"t":"usc","label":"18 U.S.C. § 521","url":"https://www.law.cornell.edu/uscode/text/18/521","subs":["(b)","(d)(3)"],"by":{"0":"18, 18"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)(1)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"0":"27","2":"21"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)","(c)(1)(A)","(c)(1)(A)(i)","(c)(1)(A)(ii)","(c)(1)(A)(iii)","(c)(1)(C)(i)(2006)","(c)(1)(C)(i)(2018)","(c)(1)(D)(ii)","(c)(3)(A)","(c)(3)(B)","(c)(1)(1988)","(c)(1)(C)","(c)(1)(D)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"3-11, 15, 24, 26-28, 32, 4, 6, 4, 4, 4, 5, 8, 10, 10, 4, 9, 9","1":"1, 2, 4, 5, 4","2":"6, 6, 6, 6, 6","4":"5, 17, 18"}},{"t":"usc","label":"18 U.S.C. § 1963","url":"https://www.law.cornell.edu/uscode/text/18/1963","subs":["(m)"],"by":{"0":"18"}},{"t":"usc","label":"18 U.S.C. § 3293","url":"https://www.law.cornell.edu/uscode/text/18/3293","by":{"0":"18"}},{"t":"usc","label":"18 U.S.C. § 3551","url":"https://www.law.cornell.edu/uscode/text/18/3551","by":{"0":"22"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)(4)","(a)(4)(i)","(a)(4)(A)(ii)","(c)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§3553. Imposition of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"12, 20, 22, 30, 30","2":"30, 47, 19"}},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(c)","(b)","(c)(1)(B)","(c)(2)"],"stext":{"head":"§3582. Imposition of a sentence of imprisonment","paras":[[0,"(a) Factors To Be Considered in Imposing a Term of Imprisonment.—The court, in determining whether to impose a term of imprisonment, and, if a term of imprisonment is to be imposed, in determining the length of the term, shall consider the factors set forth in section 3553(a) to the extent that they are applicable, recognizing that imprisonment is not an appropriate means of promoting correction and rehabilitation. In determining whether to make a recommendation concerning the type of prison facility appropriate for the defendant, the court shall consider any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a)(2)."],[0,"(b) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence to imprisonment can subsequently be—"],[1,"(1) modified pursuant to the provisions of subsection (c);"],[1,"(2) corrected pursuant to the provisions of rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified, if outside the guideline range, pursuant to the provisions of section 3742;"],[0,"a judgment of conviction that includes such a sentence constitutes a final judgment for all other purposes."],[0,"(c) Modification of an Imposed Term of Imprisonment.—The court may not modify a term of imprisonment once it has been imposed except that—"],[1,"(1) in any case—"],[2,"(A) the court, upon motion of the Director of the Bureau of Prisons, or upon motion of the defendant after the defendant has fully exhausted all administrative rights to appeal a failure of the Bureau of Prisons to bring a motion on the defendant's behalf or the lapse of 30 days from the receipt of such a request by the warden of the defendant's facility, whichever is earlier, may reduce the term of imprisonment (and may impose a term of probation or supervised release with or without conditions that does not exceed the unserved portion of the original term of imprisonment), after considering the factors set forth in section 3553(a) to the extent that they are applicable, if it finds that—"],[3,"(i) extraordinary and compelling reasons warrant such a reduction; or"],[3,"(ii) the defendant is at least 70 years of age, has served at least 30 years in prison, pursuant to a sentence imposed under section 3559(c), for the offense or offenses for which the defendant is currently imprisoned, and a determination has been made by the Director of the Bureau of Prisons that the defendant is not a danger to the safety of any other person or the community, as provided under section 3142(g);"],[2,"and that such a reduction is consistent with applicable policy statements issued by the Sentencing Commission; and"],[2,"(B) the court may modify an imposed term of imprisonment to the extent otherwise expressly permitted by statute or by Rule 35 of the Federal Rules of Criminal Procedure; and"],[1,"(2) in the case of a defendant who has been sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission pursuant to 28 U.S.C. 994(o), upon motion of the defendant or the Director of the Bureau of Prisons, or on its own motion, the court may reduce the term of imprisonment, after considering the factors set forth in section 3553(a) to the extent that they are applicable, if such a reduction is consistent with applicable policy statements issued by the Sentencing Commission."],[0,"(d) Notification Requirements.—"],[1,"(1) Terminal illness defined.—In this subsection, the term \"terminal illness\" means a disease or condition with an end-of-life trajectory."],[1,"(2) Notification.—The Bureau of Prisons shall, subject to any applicable confidentiality requirements—"],[2,"(A) in the case of a defendant diagnosed with a terminal illness—"],[3,"(i) not later than 72 hours after the diagnosis notify the defendant's attorney, partner, and family members of the defendant's condition and inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) not later than 7 days after the date of the diagnosis, provide the defendant's partner and family members (including extended family) with an opportunity to visit the defendant in person;"],[3,"(iii) upon request from the defendant or his attorney, partner, or a family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[3,"(iv) not later than 14 days of receipt of a request for a sentence reduction submitted on the defendant's behalf by the defendant or the defendant's attorney, partner, or family member, process the request;"],[2,"(B) in the case of a defendant who is physically or mentally unable to submit a request for a sentence reduction pursuant to subsection (c)(1)(A)—"],[3,"(i) inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) accept and process a request for sentence reduction that has been prepared and submitted on the defendant's behalf by the defendant's attorney, partner, or family member under clause (i); and"],[3,"(iii) upon request from the defendant or his attorney, partner, or family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[2,"(C) ensure that all Bureau of Prisons facilities regularly and visibly post, including in prisoner handbooks, staff training materials, and facility law libraries and medical and hospice facilities, and make available to prisoners upon demand, notice of—"],[3,"(i) a defendant's ability to request a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) the procedures and timelines for initiating and resolving requests described in clause (i); and"],[3,"(iii) the right to appeal a denial of a request described in clause (i) after all administrative rights to appeal within the Bureau of Prisons have been exhausted."],[1,"(3) Annual report.—Not later than 1 year after December 21, 2018, and once every year thereafter, the Director of the Bureau of Prisons shall submit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report on requests for sentence reductions pursuant to subsection (c)(1)(A), which shall include a description of, for the previous year—"],[2,"(A) the number of prisoners granted and denied sentence reductions, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(B) the number of requests initiated by or on behalf of prisoners, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(C) the number of requests that Bureau of Prisons employees assisted prisoners in drafting, preparing, or submitting, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(D) the number of requests that attorneys, partners, or family members submitted on a defendant's behalf, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(E) the number of requests approved by the Director of the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(F) the number of requests denied by the Director of the Bureau of Prisons and the reasons given for each denial, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(G) for each request, the time elapsed between the date the request was received by the warden and the final decision, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(H) for each request, the number of prisoners who died while their request was pending and, for each, the amount of time that had elapsed between the date the request was received by the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(I) the number of Bureau of Prisons notifications to attorneys, partners, and family members of their right to visit a terminally ill defendant as required under paragraph (2)(A)(ii) and, for each, whether a visit occurred and how much time elapsed between the notification and the visit;"],[2,"(J) the number of visits to terminally ill prisoners that were denied by the Bureau of Prisons due to security or other concerns, and the reasons given for each denial; and"],[2,"(K) the number of motions filed by defendants with the court after all administrative rights to appeal a denial of a sentence reduction had been exhausted, the outcome of each motion, and the time that had elapsed between the date the request was first received by the Bureau of Prisons and the date the defendant filed the motion with the court."],[0,"(e) Inclusion of an Order To Limit Criminal Association of Organized Crime and Drug Offenders.—The court, in imposing a sentence to a term of imprisonment upon a defendant convicted of a felony set forth in chapter 95 (racketeering) or 96 (racketeer influenced and corrupt organizations) of this title or in the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 801 et seq.), or at any time thereafter upon motion by the Director of the Bureau of Prisons or a United States attorney, may include as a part of the sentence an order that requires that the defendant not associate or communicate with a specified person, other than his attorney, upon a showing of probable cause to believe that association or communication with such person is for the purpose of enabling the defendant to control, manage, direct, finance, or otherwise participate in an illegal enterprise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3582?type=usc&year=mostrecent&link-type=html"},"head":"§3582. Imposition of a sentence of imprisonment","tname":"Crimes and Criminal Procedure","by":{"0":"13, 22, 23","2":"46, 30, 38, 37, 38","4":"18"}},{"t":"usc","label":"18 U.S.C. § 3584","url":"https://www.law.cornell.edu/uscode/text/18/3584","subs":["(a)"],"by":{"0":"4"}},{"t":"usc","label":"18 U.S.C. § 3742","url":"https://www.law.cornell.edu/uscode/text/18/3742","subs":["(g)","(g)(1)","(a)(1)","(b)(1)","(e)","(f)","(a)","(f)(1)"],"stext":{"head":"§3742. Review of a sentence","paras":[[0,"(a) Appeal by a Defendant.—A defendant may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines; or"],[1,"(3) is greater than the sentence specified in the applicable guideline range to the extent that the sentence includes a greater fine or term of imprisonment, probation, or supervised release than the maximum established in the guideline range, or includes a more limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the maximum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"(b) Appeal by the Government.—The Government may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is less than the sentence specified in the applicable guideline range to the extent that the sentence includes a lesser fine or term of imprisonment, probation, or supervised release than the minimum established in the guideline range, or includes a less limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the minimum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"The Government may not further prosecute such appeal without the personal approval of the Attorney General, the Solicitor General, or a deputy solicitor general designated by the Solicitor General."],[0,"(c) Plea Agreements.—In the case of a plea agreement that includes a specific sentence under rule 11(e)(1)(C) of the Federal Rules of Criminal Procedure—"],[1,"(1) a defendant may not file a notice of appeal under paragraph (3) or (4) of subsection (a) unless the sentence imposed is greater than the sentence set forth in such agreement; and"],[1,"(2) the Government may not file a notice of appeal under paragraph (3) or (4) of subsection (b) unless the sentence imposed is less than the sentence set forth in such agreement."],[0,"(d) Record on Review.—If a notice of appeal is filed in the district court pursuant to subsection (a) or (b), the clerk shall certify to the court of appeals—"],[1,"(1) that portion of the record in the case that is designated as pertinent by either of the parties;"],[1,"(2) the presentence report; and"],[1,"(3) the information submitted during the sentencing proceeding."],[0,"(e) Consideration.—Upon review of the record, the court of appeals shall determine whether the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is outside the applicable guideline range, and"],[2,"(A) the district court failed to provide the written statement of reasons required by section 3553(c);"],[2,"(B) the sentence departs from the applicable guideline range based on a factor that—"],[3,"(i) does not advance the objectives set forth in section 3553(a)(2); or"],[3,"(ii) is not authorized under section 3553(b); or"],[3,"(iii) is not justified by the facts of the case; or"],[2,"(C) the sentence departs to an unreasonable degree from the applicable guidelines range, having regard for the factors to be considered in imposing a sentence, as set forth in section 3553(a) of this title and the reasons for the imposition of the particular sentence, as stated by the district court pursuant to the provisions of section 3553(c); or"],[1,"(4) was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable."],[0,"The court of appeals shall give due regard to the opportunity of the district court to judge the credibility of the witnesses, and shall accept the findings of fact of the district court unless they are clearly erroneous and, except with respect to determinations under subsection (3)(A) or (3)(B), shall give due deference to the district court's application of the guidelines to the facts. With respect to determinations under subsection (3)(A) or (3)(B), the court of appeals shall review de novo the district court's application of the guidelines to the facts."],[0,"(f) Decision and Disposition.—If the court of appeals determines that—"],[1,"(1) the sentence was imposed in violation of law or imposed as a result of an incorrect application of the sentencing guidelines, the court shall remand the case for further sentencing proceedings with such instructions as the court considers appropriate;"],[1,"(2) the sentence is outside the applicable guideline range and the district court failed to provide the required statement of reasons in the order of judgment and commitment, or the departure is based on an impermissible factor, or is to an unreasonable degree, or the sentence was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable, it shall state specific reasons for its conclusions and—"],[2,"(A) if it determines that the sentence is too high and the appeal has been filed under subsection (a), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[2,"(B) if it determines that the sentence is too low and the appeal has been filed under subsection (b), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[1,"(3) the sentence is not described in paragraph (1) or (2), it shall affirm the sentence."],[0,"(g) Sentencing Upon Remand.—A district court to which a case is remanded pursuant to subsection (f)(1) or (f)(2) shall resentence a defendant in accordance with section 3553 and with such instructions as may have been given by the court of appeals, except that—"],[1,"(1) In determining the range referred to in subsection 3553(a)(4), the court shall apply the guidelines issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, and that were in effect on the date of the previous sentencing of the defendant prior to the appeal, together with any amendments thereto by any act of Congress that was in effect on such date; and"],[1,"(2) The court shall not impose a sentence outside the applicable guidelines range except upon a ground that—"],[2,"(A) was specifically and affirmatively included in the written statement of reasons required by section 3553(c) in connection with the previous sentencing of the defendant prior to the appeal; and"],[2,"(B) was held by the court of appeals, in remanding the case, to be a permissible ground of departure."],[0,"(h) Application to a Sentence by a Magistrate Judge.—An appeal of an otherwise final sentence imposed by a United States magistrate judge may be taken to a judge of the district court, and this section shall apply (except for the requirement of approval by the Attorney General or the Solicitor General in the case of a Government appeal) as though the appeal were to a court of appeals from a sentence imposed by a district court."],[0,"(i) Guideline Not Expressed as a Range.—For the purpose of this section, the term \"guideline range\" includes a guideline range having the same upper and lower limits."],[0,"(j) Definitions.—For purposes of this section—"],[1,"(1) a factor is a \"permissible\" ground of departure if it—"],[2,"(A) advances the objectives set forth in section 3553(a)(2); and"],[2,"(B) is authorized under section 3553(b); and"],[2,"(C) is justified by the facts of the case; and"],[1,"(2) a factor is an \"impermissible\" ground of departure if it is not a permissible factor within the meaning of subsection (j)(1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3742?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§3742. Review of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"18, 30, 29, 30","2":"30, 30, 30, 30, 30, 47, 50","4":"15, 15, 4, 5"}},{"t":"usc","label":"18 U.S.C. § 4214","url":"https://www.law.cornell.edu/uscode/text/18/4214","subs":["(d)(4)(1982)"],"by":{"0":"31"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(h)(2)","(a)"],"stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2255. Federal custody; remedies on motion attacking sentence","tname":"Judiciary and Judicial Procedure","by":{"0":"3, 9, 9","4":"15"}},{"t":"usc","label":"42 U.S.C. § 16911","url":"https://www.law.cornell.edu/uscode/text/42/16911","subs":["(1)(2012)"],"by":{"0":"27"}},{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"1":"31","2":"44","3":"18"}},{"t":"case","label":"Arizona v. Inter Tribal Council of Arizona","cite":"570 U.S. 1","y":2013,"id":"2012/12-71","sc":1,"sum":"The Court found the National Voter Registration Act preempted other voter registration requirements.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Aultman v. Seiberling","cite":"31 Ohio St. 201","y":1877,"url":"https://www.courtlistener.com/c/Ohio%20St./31/201/","by":{"1":"19"}},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"sum":"Section 406 of the Act does not authorize the imposition of a special parole term even though that sanction is included within the penalty provision of the target offense.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35, 36","2":"44","3":"19","4":"22"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"op":3,"ar":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"1":"17","3":"4"}},{"t":"case","label":"Bondholders & Purchasers of the Iron Railroad v. Toledo","cite":"62 F. 166","y":1894,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F./62/166/","by":{"1":"19"}},{"t":"case","label":"Buchanan v. Cabiness","cite":"245 S.W.2d 868","y":1951,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/245/868/","by":{"1":"20"}},{"t":"case","label":"Burks v. United States","cite":"437 U.S. 1","y":1978,"id":"1977/76-6528","sc":1,"sum":"The Double Jeopardy Clause of the Fifth Amendment precludes a second trial once the reviewing court has found the evidence insufficient to sustain the jury's verdict of guilty, and the only \"just\" remedy available for that court under 28 U. S. C. § 2106 is the entry of a judgment of acquittal.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20, 25"}},{"t":"case","label":"Camreta v. Greene","cite":"563 U.S. 692","y":2011,"id":"2010/09-1454","sc":1,"sum":"A case which the Court vacated in part and remanded in favor of the defendant without addressing the Fourth Amendment question at issue.","sumSrc":"Oyez","by":{"1":"20, 21"}},{"t":"case","label":"Cannon v. University of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15, 17, 23"}},{"t":"case","label":"Concepcion v. United States","cite":"597 U.S. 481","y":2022,"id":"2021/20-1650","sc":1,"sum":"Section 404(b) of the First Step Act of 2018, 132 Stat. 5222, allows district courts to consider intervening changes of law or fact in exercising their discretion to reduce a sentence.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"9, 29, 34","2":"16, 20, 25, 38, 46","4":"2, 3, 5, 13"}},{"t":"case","label":"Connecticut National Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"op":1,"sum":"Under 18 U. S. C. §1028A(a)(1)’s crime of “aggravated identity theft,” a defendant “uses” another person’s means of identification “in relation to” a predicate offense when the use is at the crux of what makes the conduct criminal.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16, 32","4":"2, 17"}},{"t":"case","label":"Farnsworth v. Western Union Telephone Co.","cite":"6 N.Y.S. 735","y":1889,"court":"Gen. Term","url":"https://www.courtlistener.com/c/N.Y.S./6/735/","by":{"1":"19, 23"}},{"t":"case","label":"Fiswick v. United States","cite":"329 U.S. 211","y":1946,"id":"scdb/1946-014","sc":1,"op":1,"sum":"thai the conspiracy charged and proved did not extend beyond the date of the last overt act, and that admittance in evidence against all of the Statement of the Case. petitioners of admissions made after that date by one of the petitioners was reversible error.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20, 21","2":"20"}},{"t":"case","label":"Green v. McCarter","cite":"42 S.E. 157","y":1902,"court":"S.C.","url":"https://www.courtlistener.com/c/S.E./42/157/","by":{"1":"19","2":"27"}},{"t":"case","label":"Harris v. Rivera","cite":"454 U.S. 339","y":1981,"id":"1981/81-17","sc":1,"sum":"A New York trial judge, sitting without a jury, convicted respondent and his wife but acquitted their codefendant on charges arising out of a robbery, notwithstanding if the judge had credited the testimony of the prosecution's main witness (the victim), he presumably would have convicted all three defendants or, conversely, if he had credited the testimony of the only defense witness (the codefendant), he …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Holloway v. United States","cite":"526 U.S. 1","y":1999,"id":"1998/97-7164","sc":1,"sum":"Announced by Justice John Paul Stevens, the Court ruled that the federal carjacking law applies to carjacking crimes committed with \"conditional intent\" of harming drivers who refuse a carjacker's demands. \"The intent requirement...is satisfied when the government proves that at the moment the defendant demanded or took control over the driver's automobile the defendant possessed the intent to seriously harm or kill the driver if necessary to steal the car,\" wrote Justice Stevens.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Mississippi ex rel. Hood v. AU Optronics Corp.","cite":"571 U.S. 161","y":2014,"id":"2013/12-1036","sc":1,"sum":"The Court ruled that, in order for a case to be removed to a federal district court instead of a state court under the Class Action Fairness Act, at least 100 people must be represented by the lawsuit.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Intel Corp. Investment Policy Committee v. Sulyma","cite":"589 U.S. 178","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Kelly v. Robinson","cite":"479 U.S. 36","y":1986,"id":"1986/85-1033","sc":1,"sum":"Section 523(a)(7) preserves from discharge in Chapter 7 any condition a state criminal court imposes as part of a criminal sentence. Thus, restitution obligations, imposed as conditions of probation in state criminal proceedings, are not dischargeable.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Landgraf v. USI Film Productions","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Lawson v. Bissell","cite":"7 Ohio St. 129","y":1857,"url":"https://www.courtlistener.com/c/Ohio%20St./7/129/","by":{"1":"19, 25"}},{"t":"case","label":"Lockwood v. Jones","cite":"7 Conn. 431","y":1829,"url":"https://www.courtlistener.com/c/Conn./7/431/","by":{"1":"18","2":"27"}},{"t":"case","label":"Martinez v. Illinois","cite":"572 U.S. 833","y":2014,"id":"2013/13-5967","sc":1,"op":1,"sum":"The Court found that jeopardy comes into effect in a trial when the jury is sworn in, regardless if one party fails to participate.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Miller v. Schlereth","cite":"36 N.W.2d 497","y":1949,"court":"Neb.","url":"https://www.courtlistener.com/c/N.W.2d/36/497/","by":{"1":"20"}},{"t":"case","label":"Mitchell v. Joseph","cite":"117 F.2d 253","y":1941,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/117/253/","by":{"1":"20","2":"27"}},{"t":"case","label":"Norman v. Norman","cite":"207 P. 970","y":1922,"court":"Okla.","url":"https://www.courtlistener.com/c/P./207/970/","by":{"1":"18"}},{"t":"case","label":"North Carolina v. Pearce","cite":"395 U.S. 711","y":1969,"id":"1968/413","sc":1,"op":2,"sum":"Stating vacatur causes a conviction to be “ `wholly nullifed and the slate wiped clean' ”.","sumSrc":"opinion","by":{"1":"21","2":"22","4":"2, 8, 10, 20"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"589 U.S. 8","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Shular v. United States","cite":"589 U.S. 154","y":2020,"id":"2019/18-6662","sc":1,"sum":"The Court held that the Armed Career Criminal Act’s “serious drug offense” definition requires only that a state offense involve the conduct specified in the statute; it does not require that the state offense match certain generic offenses.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"sum":"The Court held that the former CEO of Enron received a fair trial before an impartial jury, and that the federal law that makes it a crime to deprive someone of a fair and honest trial only applies to bribery and kickback schemes.","sumSrc":"Oyez","by":{"1":"35","2":"44"}},{"t":"case","label":"Star Athletica, LLC v. Varsity Brands, Inc.","cite":"580 U.S. 405","y":2017,"id":"2016/15-866","sc":1,"sum":"The Court determined that the test for deciding whether a feature of a “useful article” is copyrightable under the Copyright Act is whether the feature can be perceived as a two- or three-dimensional artwork that is separable from the useful article and if it would be a protectable pictorial, graphical, or sculptural work on its own.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Staub v. Proctor Hospital","cite":"562 U.S. 411","y":2011,"id":"2010/09-400","sc":1,"op":1,"sum":"The Court held that an employer may be found liable for the discriminatory acts of supervisors, who do not themselves make employment decisions but do influence the employment decision-makers.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Stewart v. Oneal","cite":"237 F. 897","y":1916,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F./237/897/","by":{"1":"19"}},{"t":"case","label":"Strickland v. Flagstaff Silver Mining Co.","cite":"1 Utah 199","y":1875,"url":"https://www.courtlistener.com/c/Utah/1/199/","by":{"1":"19"}},{"t":"case","label":"Tims v. Holland Furnace Co.","cite":"90 N.E.2d 376","y":1950,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E.2d/90/376/","by":{"1":"20"}},{"t":"case","label":"United States v. Angelos","cite":"345 F. Supp. 2d 1227","y":2004,"court":"D. Utah","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/345/1227/","op":2,"by":{"1":"5","2":"7"}},{"t":"case","label":"United States v. Bethea","cite":"841 F. App’x 544","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/841/544/","by":{"1":"8"}},{"t":"case","label":"United States v. Burke","cite":"863 F.3d 1355","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/863/1355/","by":{"1":"33"}},{"t":"case","label":"United States v. Carpenter","cite":"80 F.4th 790","y":2023,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/80/790/","op":1,"ar":1,"by":{"1":"23"}},{"t":"case","label":"United States v. Duffey","cite":"456 F. App’x 434","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/456/434/","op":8,"by":{"1":"9","2":"10"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"sum":"The Court held 7-2 that the U.S. Code's section 3565 refers to the original sentence range set by U.S. Sentencing Guidelines. Therefore, the minimum revocation sentence for drug possession while on probation is one third the maximum of the Guidelines range of imprisonment; the maximum revocation sentence is the Guidelines maximum.","sumSrc":"Oyez","by":{"1":"36, 37","3":"19"}},{"t":"case","label":"United States v. Hernandez","cite":"107 F.4th 965","y":2024,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/107/965/","op":2,"by":{"1":"22, 24-27, 29","3":"12","4":"18"}},{"t":"case","label":"United States v. Holloway","cite":"68 F. Supp. 3d 310","y":2014,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/68/310/","op":1,"sum":"Noting that § 924(c) stacking “produce[d] sentences that would be laughable if only there weren't real people on the receiving end of them”.","sumSrc":"opinion","by":{"1":"5"}},{"t":"case","label":"United States v. Hungerford","cite":"465 F.3d 1113","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/465/1113/","op":1,"by":{"1":"5, 34"}},{"t":"case","label":"United States v. Hunter","cite":"770 F.3d 740","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/770/740/","op":1,"by":{"1":"5"}},{"t":"case","label":"United States v. Jackson","cite":"995 F.3d 522","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/995/522/","op":2,"sum":"Holding that such an offender does not beneft from the Act at resentencing, if the prior sentence was vacated after the Act's enactment.","sumSrc":"opinion","by":{"1":"25","2":"35"}},{"t":"case","label":"United States v. Mayse","cite":"5 F.2d 885","y":1925,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/5/885/","by":{"1":"19"}},{"t":"case","label":"United States v. Munsingwear","cite":"340 U.S. 36","y":1950,"id":"scdb/1950-004","sc":1,"sum":"The dismissal is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20","2":"25","4":"11"}},{"t":"case","label":"United States v. Ross","cite":"582 F. App’x 528","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/582/528/","by":{"1":"9","2":"11"}},{"t":"case","label":"US Airways, Inc. v. McCutchen","cite":"569 U.S. 88","y":2013,"id":"2012/11-1285","sc":1,"sum":"The Court held that when a contract is silent on allocation of relief, the parties' intentions are best determined by the common-fund doctrine.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Williams v. Floyd","cite":"27 N.C. 649","y":1845,"url":"https://www.courtlistener.com/c/N.C./27/649/","by":{"1":"19"}},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"35, 36, 37","4":"22"}},{"t":"case","label":"Wrang v. Spencer","cite":"235 A.2d 861","y":1967,"court":"Conn. App. Ct.","url":"https://www.courtlistener.com/c/A.2d/235/861/","by":{"1":"20"}},{"t":"case","label":"Bagley v. CMC Real Estate Corp.","cite":"923 F.2d 758","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/923/758/","by":{"2":"25"}},{"t":"case","label":"Ball v. United States","cite":"163 U.S. 662","y":1896,"id":"scdb/1895-270","sc":1,"sum":"A general verdict of acquittal, in a court having jurisdiction of the canse and of the defendant, upon the issue of not guilty to an indictment undertaking to charge murder, and not objected to before verdict as insufficient In that respect, Is a bar to a subsequent indictment against him for the same killing.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"21","3":"7"}},{"t":"case","label":"Berman v. United States","cite":"302 U.S. 211","y":1937,"id":"scdb/1937-024","sc":1,"sum":"1. The sentence in a criminal case is the final judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17"}},{"t":"case","label":"Bradley v. Milliken","cite":"772 F.2d 266","y":1985,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/772/266/","by":{"2":"25"}},{"t":"case","label":"Bradley v. United States","cite":"410 U.S. 605","y":1973,"id":"1972/71-1304","sc":1,"sum":"On May 6, 1971, petitioners were convicted and sentenced for narcotics offenses committed in March 1971. They received the minimum five-year sentences under a provision that was mandatory and made the sentences not subject to suspension, probation, or parole. Effective May 1, 1971, that provision was repealed and liberalized by the Comprehensive Drug Abuse Prevention and Control Act of 1970. On petitioners' motion …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"45"}},{"t":"case","label":"Burrage v. United States","cite":"571 U.S. 204","y":2014,"id":"2013/12-7515","sc":1,"sum":"The Court held that, under 21 U.S.C. § 841(b) of the statute regarding drug-related deaths, an individual convicted of the death of another through the sale of drugs cannot be convicted of drug-induced homicide if multiple drugs are present in the deceased's system.","sumSrc":"Oyez","by":{"2":"42, 43","4":"2, 21"}},{"t":"case","label":"Chavez-Meza v. United States","cite":"585 U.S. 109","y":2018,"id":"2017/17-5639","sc":1,"sum":"The Court held that because the record in this case as a whole demonstrated that the judge had a reasoned basis for his decision, the judge’s explanation for reducing Adaucto Chavez-Meza’s sentence under 18 U.S.C. § 3582(c)(2) to the middle instead of the bottom of the amended Federal Guidelines range was adequate.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Coleman v. Tennessee","cite":"97 U.S. 509","y":1878,"id":"scdb/1878-108","sc":1,"by":{"2":"20"}},{"t":"case","label":"Cruz-Garza v. Ashcroft","cite":"396 F.3d 1125","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/396/1125/","by":{"2":"24"}},{"t":"case","label":"Dickerson v. New Banner Inst., Inc.","cite":"460 U.S. 103","y":1983,"id":"1982/81-1180","sc":1,"sum":"The firearms disabilities imposed by §§ 922(g)(1) and (h)(1) apply to Kennison and were not removed by the expunction of the record of his guilty plea to the concealed weapon charge.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"3, 16, 21","4":"6, 7"}},{"t":"case","label":"Dodrill v. Ludt","cite":"764 F.2d 442","y":1985,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/764/442/","by":{"2":"25"}},{"t":"case","label":"Dung Phan v. Holder","cite":"667 F.3d 448","y":2012,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/667/448/","by":{"2":"24"}},{"t":"case","label":"Durning v. Citibank, N.A.","cite":"950 F.2d 1419","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/950/1419/","sum":"Explaining that an order “may be reversed on other grounds” but there is no such thing as an order “vacated” on other grounds—that order simply does not exist.","sumSrc":"brief:2","by":{"2":"25"}},{"t":"case","label":"Fischer v. United States","cite":"144 S. Ct. 2176","y":2024,"id":"2023/23-5572","sc":1,"sum":"The Court held that 18 U.S.C. § 1512(c), which prohibits obstruction of congressional inquiries and investigations, does not include acts unrelated to investigations and evidence.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Garces v. U.S. Att’y Gen.","cite":"611 F.3d 1337","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/611/1337/","by":{"2":"24"}},{"t":"case","label":"Green v. United States","cite":"365 U.S. 301","y":1961,"id":"1960/70","sc":1,"sum":"The judgment is affirmed. Pp. 302-306. 273 F. 2d 216 and 274 F. 2d 59, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Greenlaw v. United States","cite":"554 U.S. 237","y":2008,"id":"2007/07-330","sc":1,"op":3,"sum":"The Court stated that the Eighth Circuit could not order the district court to increase Greenlaw's sentence without a request from the government to do so. The Court pointed to several of its precedents for the rule that a remedy in favor the appellee, in this case the government, can only be justified if the appellee brings a cross-appeal.","sumSrc":"Oyez","by":{"2":"23","4":"12"}},{"t":"case","label":"Herrera-Inirio v. INS","cite":"208 F.3d 299","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/208/299/","by":{"2":"24"}},{"t":"case","label":"Johnson v. Mississippi","cite":"486 U.S. 578","y":1988,"id":"1987/87-5468","sc":1,"sum":"By allowing petitioner's death sentence to stand despite the fact that it was based in part on the vacated New York conviction, the Mississippi Supreme Court violated the Eighth Amendment's prohibition against cruel and unusual punishment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"Lawson v. FMR LLC","cite":"571 U.S. 429","y":2014,"id":"2013/12-3","sc":1,"sum":"The Court held that the whistleblower-protection section of the Sarbanes-Oxley Act applies to privately-employed individuals.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Lewis v. United States","cite":"445 U.S. 55","y":1980,"id":"1979/78-1595","sc":1,"op":6,"sum":"Even though petitioner's extant prior state-court felony conviction may be subject to collateral attack under Gideon v. Wainwright, 372 U. S. 335, it could properly be used as a predicate for his subsequent conviction for possession of a firearm in violation of § 1202 (a) (1) of Title VII of the Omnibus Crime Control and Safe Streets Act of 1968.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21","3":"13","4":"6, 7, 15"}},{"t":"case","label":"Limtiaco v. Camacho","cite":"549 U.S. 483","y":2007,"id":"2006/06-116","sc":1,"sum":"The majority opinion by Justice Clarence Thomas held that, contrary to the Guam Supreme Court's interpretation, the phrase must mean the assessed value for tax purposes of property on Guam. \"The word 'tax' modifies 'valuation,' not 'property,'\" the Court reasoned, so \"tax valuation\" \"refers to the type of valuation to be conducted, not the object that is valued.\" The dissenting Justices argued that deciding the case on the basis of textual analysis and comparison to state debt limitations would amount to a \"coin toss.\" In the dissenters' view, Congress's purpose was to set a \"hard cap\" on debt, which would indicate that the debt limitation should be based on the full market (appraised) value of property on Guam rather than dependent on the changeable assessment rate.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"McBoyle v. United States","cite":"283 U.S. 25","y":1931,"id":"scdb/1930-139","sc":1,"sum":"The National Motor Vehicle Theft Act, U. S. C., Title 18, § 408, which punishes whoever transports, or causes to be transported, in interstate or foreign commerce a motor vehicle knowing it to have been stolen, and which defines \"motor vehicle\" as including \"an automobile, automobile truck, automobile wagon, motor cycle, or any other self-propelled vehicle not designed for running on rails,\" does not apply to …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"43, 44","3":"1, 14"}},{"t":"case","label":"Miller v. Aderhold","cite":"288 U.S. 206","y":1933,"id":"scdb/1932-109","sc":1,"sum":"1. One upon whom sentence in a criminal case has been suspended may at any time request the court to pronounce judgment, and in the absence of such request must be deemed to have consented to the indefinite delay.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17","4":"10, 16, 18, 20"}},{"t":"case","label":"Nath v. Gonzales","cite":"467 F.3d 1185","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/467/1185/","by":{"2":"24"}},{"t":"case","label":"O’Connor v. Donaldson","cite":"422 U.S. 563","y":1975,"id":"1974/74-8","sc":1,"sum":"While the trial court properly instructed the jury on the relevance of O’Connor’s good faith intentions, Justice Stewart held that the Fifth Circuit must determine if the trial court properly instructed the jury on O’Connor’s reliance on state law. Justice Stewart acknowledged that the state cannot constitutionally confine a non-dangerous, mentally ill person capable of living outside of a mental health facility.","sumSrc":"Oyez","by":{"2":"25","4":"11"}},{"t":"case","label":"People v. Hunter","cite":"104 N.E.3d 358","y":2017,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E.3d/104/358/","by":{"2":"47"}},{"t":"case","label":"Pickering v. Gonzales","cite":"465 F.3d 263","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/465/263/","by":{"2":"24"}},{"t":"case","label":"Rumierz v. Gonzales","cite":"456 F.3d 31","y":2006,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/456/31/","by":{"2":"24"}},{"t":"case","label":"Saleh v. Gonzales","cite":"495 F.3d 17","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/495/17/","by":{"2":"24","4":"9"}},{"t":"case","label":"Serfass v. United States","cite":"420 U.S. 377","y":1975,"id":"1974/73-1424","sc":1,"sum":"The Double Jeopardy Clause does not bar an appeal by the United States under 18 U. S. C. § 3731 from a pretrial order dismissing an indictment since in that situation the criminal defendant has not been \"put to trial before the trier of the facts, whether the trier be a jury or a judge.\" United States v. Jom, 400 U. S. 470, 479.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Simpson v. Motorists Mut. Ins. Co.","cite":"494 F.2d 850","y":1974,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/494/850/","by":{"2":"25"}},{"t":"case","label":"Southwest Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"id":"2021/21-309","sc":1,"sum":"Airplane cargo loaders and ramp supervisors who, like petitioner Saxon, frequently load and unload airplane cargo belong to a “class of workers engaged in foreign or interstate commerce” exempt from the Federal Arbitration Act’s coverage.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"32"}},{"t":"case","label":"State v. Waxler","cite":"69 N.E.3d 1132","y":2016,"court":"Ohio Ct. App.","url":"https://www.courtlistener.com/c/N.E.3d/69/1132/","by":{"2":"47","4":"23"}},{"t":"case","label":"Tibbs v. Florida","cite":"457 U.S. 31","y":1982,"id":"1981/81-5114","sc":1,"sum":"Where the Florida Supreme Court's reversal of petitioner's murder and rape convictions at a jury trial was based on the weight of the evidence, a retrial is not barred by the Double Jeopardy Clause of the Fifth Amendment as made applicable to the States by the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21, 22"}},{"t":"case","label":"United States v. Barnes","cite":"948 F.2d 325","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/948/325/","by":{"2":"19","4":"11"}},{"t":"case","label":"United States v. Cox","cite":"245 F.3d 126","y":2001,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/245/126/","by":{"2":"22"}},{"t":"case","label":"United States v. Figueroa-Labrada","cite":"780 F.3d 1294","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/780/1294/","by":{"2":"20"}},{"t":"case","label":"United States v. Flack","cite":"941 F.3d 238","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/941/238/","by":{"2":"19, 20"}},{"t":"case","label":"United States v. Garcia-Robles","cite":"640 F.3d 159","y":2011,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/640/159/","by":{"2":"18, 19","4":"12"}},{"t":"case","label":"United States v. Guthrie","cite":"931 F.2d 564","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/931/564/","by":{"2":"22, 23"}},{"t":"case","label":"United States v. Jerry","cite":"487 F.2d 600","y":1973,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/487/600/","by":{"2":"28"}},{"t":"case","label":"United States v. Maldonado","cite":"996 F.2d 598","y":1993,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/996/598/","by":{"2":"19"}},{"t":"case","label":"United States v. Mobley","cite":"833 F.3d 797","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/833/797/","by":{"2":"19"}},{"t":"case","label":"United States v. Moree","cite":"928 F.2d 654","y":1991,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/928/654/","by":{"2":"19"}},{"t":"case","label":"United States v. Muhammad","cite":"478 F.3d 247","y":2007,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/478/247/","by":{"2":"19"}},{"t":"case","label":"United States v. Rivera-Ruperto","cite":"852 F.3d 1","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/852/1/","by":{"2":"7"}},{"t":"case","label":"United States v. Scott","cite":"437 U.S. 82","y":1978,"id":"1977/76-1382","sc":1,"sum":"Where a defendant himself seeks to have his trial terminated without any submission to either judge or jury as to his guilt or innocence, an appeal by the Government from his successful effort to do so does not offend the Double Jeopardy Clause, and hence is not barred by 18 U. S. C. § 3731 (1976 ed.). United States v. Jenkins, supra, overruled.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"United States v. Taylor","cite":"648 F.3d 417","y":2011,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/648/417/","by":{"2":"50"}},{"t":"case","label":"United States v. Wiltberger","cite":"5 Wheat. 76","y":1820,"url":"https://www.courtlistener.com/c/Wheat./5/76/","by":{"2":"44"}},{"t":"case","label":"Williamson v. United States","cite":"265 F.2d 236","y":1959,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/265/236/","by":{"2":"19","4":"11"}},{"t":"case","label":"Page(s) Wooden v. United States","cite":"595 U.S. 360","y":2022,"url":"https://supreme.justia.com/cases/federal/us/595/360/","sc":1,"op":34,"by":{"2":"36"}},{"t":"case","label":"Wynne v. Rochelle","cite":"385 F.2d 789","y":1967,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/385/789/","by":{"2":"27"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(48)(A)"],"by":{"2":"23"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)(2)(A)(i)"],"by":{"2":"23"}},{"t":"usc","label":"18 U.S.C. § 3559","url":"https://www.law.cornell.edu/uscode/text/18/3559","subs":["(c)(7)"],"by":{"2":"30"}},{"t":"usc","label":"18 U.S.C. § 3613A","url":"https://www.law.cornell.edu/uscode/text/18/3613A","subs":["(a)(1)"],"by":{"2":"30"}},{"t":"usc","label":"18 U.S.C. § 3614","url":"https://www.law.cornell.edu/uscode/text/18/3614","subs":["(a)"],"by":{"2":"30"}},{"t":"usc","label":"18 U.S.C. § 3661","url":"https://www.law.cornell.edu/uscode/text/18/3661","by":{"2":"29"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)","(b)(1)(A)"],"by":{"2":"43, 43"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"2":"5"}},{"t":"rule","label":"Fed. R. Crim. P. 32","url":"https://www.law.cornell.edu/rules/frcrmp/rule_32","subs":["(i)(4)(A)(ii)"],"by":{"2":"18"}},{"t":"rule","label":"Fed. R. Crim. P. 43","url":"https://www.law.cornell.edu/rules/frcrmp/rule_43","subs":["(a)(3)","(b)(4)"],"by":{"2":"19, 38"}},{"t":"case","label":"Biden v. Nebraska","cite":"143 S. Ct. 2355","y":2023,"id":"2022/22-506","sc":1,"ar":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"3, 4, 18"}},{"t":"case","label":"Comcast Corp. v. NAAAOM","cite":"589 U.S. 327","y":2020,"url":"https://supreme.justia.com/cases/federal/us/589/327/","sc":1,"by":{"3":"1"}},{"t":"case","label":"Corner Post v. Federal Reserve","cite":"603 U.S. 799","y":2024,"url":"https://supreme.justia.com/cases/federal/us/603/799/","sc":1,"by":{"3":"5"}},{"t":"case","label":"Dolan v. Postal Service","cite":"546 U.S. 481","y":2006,"id":"2005/04-848","sc":1,"sum":"The Court ruled that the \"negligent transmission\" exception was inapplicable to Dolan's case, and therefore sovereign immunity had been waived and her case could proceed. The Court accepted Dolan's argument that the exception was only meant to encompass cases of late, missing, or incorrectly delivered mail.","sumSrc":"Oyez","by":{"3":"3"}},{"t":"case","label":"Graham County Soil & Water Conservation District v. U.S. ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"sum":"The Court held that an audit performed by a state or its political subdivisions constitutes an administrative report within the False Claims Act.","sumSrc":"Oyez","by":{"3":"3"}},{"t":"case","label":"Harrington v. Purdue Pharma","cite":"144 S. Ct. 2071","y":2024,"id":"2023/23-124","sc":1,"ar":1,"sum":"The bankruptcy code does not authorize a release and injunction that, as part of a plan of reorganization under Chapter 11, effectively seek to discharge claims against a nondebtor without the consent of affected claimants.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"18"}},{"t":"case","label":"Honeycutt v. United States","cite":"581 U.S. 443","y":2017,"id":"2016/16-142","sc":1,"sum":"The Court determined that the federal forfeiture statute does not require joint and several liability among co-conspirators for any reasonably foreseeable proceeds of conspiracy.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"sum":"The Court held that 18 USC section 3583(h) is not retroactively applicable; however, its prior version, 18 USC section 3583(e)(3), authorizes a Federal District Court to impose additional term of supervised release after revocation of initial term and reimprisonment.","sumSrc":"Oyez","by":{"3":"19, 20"}},{"t":"case","label":"Johnson v. United States","cite":"544 U.S. 295","y":2005,"id":"2004/03-9685","sc":1,"sum":"The Court held that by waiting until more than three years after his federal sentence, Johnson failed to show due diligence in seeking to have his original state convictions vacated.","sumSrc":"Oyez","by":{"3":"9"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"144 S. Ct. 2244","y":2024,"id":"2023/22-451","sc":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"19"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"McFadden v. United States","cite":"576 U.S. 186","y":2015,"id":"2014/14-378","sc":1,"op":1,"sum":"The Court decided that in order to fulfill the intent element of The Controlled Substance Analogue Enforcement Act of 1986, a person must either know that the substance is a controlled substance or be aware of what the substance is without knowing that it is controlled.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"MOAC Mall Holdings v. Transform Holdco","cite":"598 U.S. 288","y":2023,"id":"2022/21-1270","sc":1,"sum":"Section 363(m) of the Bankruptcy Code—which restricts the effects of certain successful appeals of judicially authorized sales or leases of bankruptcy-estate property—is not a jurisdictional provision.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"5"}},{"t":"case","label":"NFIB v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"op":3,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"3":"1"}},{"t":"case","label":"North Carolina v. Pearce","cite":"325 U.S. 711","y":1969,"id":"scdb/1944-110","sc":1,"sum":"1. The contention that an award of the National Railroad Adjustment Board under the Railway Labor Act amounts to nothing more than an advisory opinion is inconsistent with the terms, purposes and legislative history of the Act and with decisions of this Court construing it.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"7"}},{"t":"case","label":"Patel v. Garland","cite":"596 U.S. 328","y":2022,"id":"2021/20-979","sc":1,"sum":"Federal courts lack jurisdiction to review facts found as part of any judgment relating to the granting of discretionary-relief in immigration proceedings enumerated under 8 U. S. C. §1252(a)(2)(B)(i).","sumSrc":"Holding (supremecourt.gov)","by":{"3":"15"}},{"t":"case","label":"Toussie v. United States","cite":"397 U.S. 112","y":1970,"id":"1969/441","sc":1,"sum":"The offense is not a continuing one but was committed by petitioner's failure to register in 1959, when the statute of limitations began to run. Pp. 114-124. 410 F. 2d 1156, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"9"}},{"t":"case","label":"United States v. Rosenwasser","cite":"323 U.S. 360","y":1945,"id":"scdb/1944-130","sc":1,"sum":"The Fair Labor Standards Act of 1938 is applicable to employees compensated on a piece rate basis, and employers of such employees are subject to the criminal provisions of the Act. P. 361. Reversed. APPEAL under the Criminal Appeals Act from a judgment sustaining a demurrer as to certain counts of an information charging violations of the Fair Labor Standards Act. Mr. Ralph F. Fuchs, with whom Solicitor General …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"15"}},{"t":"case","label":"United States v. Sanders","cite":"909 F.3d 895","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/909/895/","by":{"3":"9"}},{"t":"case","label":"United States v. Taylor","cite":"596 U.S. 845","y":2015,"id":"2021/20-1459","sc":1,"sum":"Attempted Hobbs Act robbery does not qualify as a “crime of violence” under 18 U. S. C. §924(c)(3)(A) because no element of the offense requires proof that the defendant used, attempted to use, or threatened to use force.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"17"}},{"t":"usc","label":"18 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/18/921","subs":["(a)(20)(B)","(a)(20)"],"stext":{"head":"§921. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"person\" and the term \"whoever\" include any individual, corporation, company, association, firm, partnership, society, or joint stock company."],[0,"(2) The term \"interstate or foreign commerce\" includes commerce between any place in a State and any place outside of that State, or within any possession of the United States (not including the Canal Zone) or the District of Columbia, but such term does not include commerce between places within the same State but through any place outside of that State. The term \"State\" includes the District of Columbia, the Commonwealth of Puerto Rico, and the possessions of the United States (not including the Canal Zone)."],[0,"(3) The term \"firearm\" means (A) any weapon (including a starter gun) which will or is designed to or may readily be converted to expel a projectile by the action of an explosive; (B) the frame or receiver of any such weapon; (C) any firearm muffler or firearm silencer; or (D) any destructive device. Such term does not include an antique firearm."],[0,"(4) The term \"destructive device\" means—"],[1,"(A) any explosive, incendiary, or poison gas—"],[2,"(i) bomb,"],[2,"(ii) grenade,"],[2,"(iii) rocket having a propellant charge of more than four ounces,"],[2,"(iv) missile having an explosive or incendiary charge of more than one-quarter ounce,"],[2,"(v) mine, or"],[2,"(vi) device similar to any of the devices described in the preceding clauses;"],[1,"(B) any type of weapon (other than a shotgun or a shotgun shell which the Attorney General finds is generally recognized as particularly suitable for sporting purposes) by whatever name known which will, or which may be readily converted to, expel a projectile by the action of an explosive or other propellant, and which has any barrel with a bore of more than one-half inch in diameter; and"],[1,"(C) any combination of parts either designed or intended for use in converting any device into any destructive device described in subparagraph (A) or (B) and from which a destructive device may be readily assembled."],[0,"The term \"destructive device\" shall not include any device which is neither designed nor redesigned for use as a weapon; any device, although originally designed for use as a weapon, which is redesigned for use as a signaling, pyrotechnic, line throwing, safety, or similar device; surplus ordnance sold, loaned, or given by the Secretary of the Army pursuant to the provisions of section 7684(2), 7685, or 7686 of title 10; or any other device which the Attorney General finds is not likely to be used as a weapon, is an antique, or is a rifle which the owner intends to use solely for sporting, recreational or cultural purposes."],[0,"(5) The term \"shotgun\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire through a smooth bore either a number of ball shot or a single projectile for each single pull of the trigger."],[0,"(6) The term \"short-barreled shotgun\" means a shotgun having one or more barrels less than eighteen inches in length and any weapon made from a shotgun (whether by alteration, modification or otherwise) if such a weapon as modified has an overall length of less than twenty-six inches."],[0,"(7) The term \"rifle\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire only a single projectile through a rifled bore for each single pull of the trigger."],[0,"(8) The term \"short-barreled rifle\" means a rifle having one or more barrels less than sixteen inches in length and any weapon made from a rifle (whether by alteration, modification, or otherwise) if such weapon, as modified, has an overall length of less than twenty-six inches."],[0,"(9) The term \"importer\" means any person engaged in the business of importing or bringing firearms or ammunition into the United States for purposes of sale or distribution; and the term \"licensed importer\" means any such person licensed under the provisions of this chapter."],[0,"(10) The term \"manufacturer\" means any person engaged in the business of manufacturing firearms or ammunition for purposes of sale or distribution; and the term \"licensed manufacturer\" means any such person licensed under the provisions of this chapter."],[0,"(11) The term \"dealer\" means (A) any person engaged in the business of selling firearms at wholesale or retail, (B) any person engaged in the business of repairing firearms or of making or fitting special barrels, stocks, or trigger mechanisms to firearms, or (C) any person who is a pawnbroker. The term \"licensed dealer\" means any dealer who is licensed under the provisions of this chapter."],[0,"(12) The term \"pawnbroker\" means any person whose business or occupation includes the taking or receiving, by way of pledge or pawn, of any firearm as security for the payment or repayment of money."],[0,"(13) The term \"collector\" means any person who acquires, holds, or disposes of firearms as curios or relics, as the Attorney General shall by regulation define, and the term \"licensed collector\" means any such person licensed under the provisions of this chapter."],[0,"(14) The term \"indictment\" includes an indictment or information in any court under which a crime punishable by imprisonment for a term exceeding one year may be prosecuted."],[0,"(15) The term \"fugitive from justice\" means any person who has fled from any State to avoid prosecution for a crime or to avoid giving testimony in any criminal proceeding."],[0,"(16) The term \"antique firearm\" means—"],[1,"(A) any firearm (including any firearm with a matchlock, flintlock, percussion cap, or similar type of ignition system) manufactured in or before 1898; or"],[1,"(B) any replica of any firearm described in subparagraph (A) if such replica—"],[2,"(i) is not designed or redesigned for using rimfire or conventional centerfire fixed ammunition, or"],[2,"(ii) uses rimfire or conventional centerfire fixed ammunition which is no longer manufactured in the United States and which is not readily available in the ordinary channels of commercial trade; or"],[1,"(C) any muzzle loading rifle, muzzle loading shotgun, or muzzle loading pistol, which is designed to use black powder, or a black powder substitute, and which cannot use fixed ammunition. For purposes of this subparagraph, the term \"antique firearm\" shall not include any weapon which incorporates a firearm frame or receiver, any firearm which is converted into a muzzle loading weapon, or any muzzle loading weapon which can be readily converted to fire fixed ammunition by replacing the barrel, bolt, breechblock, or any combination thereof."],[0,"(17)(A) The term \"ammunition\" means ammunition or cartridge cases, primers, bullets, or propellent powder designed for use in any firearm."],[0,"(B) The term \"armor piercing ammunition\" means—"],[1,"(i) a projectile or projectile core which may be used in a handgun and which is constructed entirely (excluding the presence of traces of other substances) from one or a combination of tungsten alloys, steel, iron, brass, bronze, beryllium copper, or depleted uranium; or"],[1,"(ii) a full jacketed projectile larger than .22 caliber designed and intended for use in a handgun and whose jacket has a weight of more than 25 percent of the total weight of the projectile."],[0,"(C) The term \"armor piercing ammunition\" does not include shotgun shot required by Federal or State environmental or game regulations for hunting purposes, a frangible projectile designed for target shooting, a projectile which the Attorney General finds is primarily intended to be used for sporting purposes, or any other projectile or projectile core which the Attorney General finds is intended to be used for industrial purposes, including a charge used in an oil and gas well perforating device."],[0,"(18) The term \"Attorney General\" means the Attorney General of the United States 1"],[0,"(19) The term \"published ordinance\" means a published law of any political subdivision of a State which the Attorney General determines to be relevant to the enforcement of this chapter and which is contained on a list compiled by the Attorney General, which list shall be published in the Federal Register, revised annually, and furnished to each licensee under this chapter."],[0,"(20) The term \"crime punishable by imprisonment for a term exceeding one year\" does not include—"],[1,"(A) any Federal or State offenses pertaining to antitrust violations, unfair trade practices, restraints of trade, or other similar offenses relating to the regulation of business practices, or"],[1,"(B) any State offense classified by the laws of the State as a misdemeanor and punishable by a term of imprisonment of two years or less."],[0,"What constitutes a conviction of such a crime shall be determined in accordance with the law of the jurisdiction in which the proceedings were held. Any conviction which has been expunged, or set aside or for which a person has been pardoned or has had civil rights restored shall not be considered a conviction for purposes of this chapter, unless such pardon, expungement, or restoration of civil rights expressly provides that the person may not ship, transport, possess, or receive firearms."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/921?type=usc&year=mostrecent&link-type=html"},"head":"§921. Definitions","tname":"Crimes and Criminal Procedure","by":{"3":"8","4":"4"}},{"t":"case","label":"Bell v. United States","cite":"349 U.S. 81","y":1955,"id":"scdb/1954-072","sc":1,"sum":"Petitioner committed but a single offense, and was not subject to cumulative punishment under the two counts.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"22"}},{"t":"case","label":"Bittner v. United States","cite":"598 U.S. 85","y":2023,"id":"2022/21-1195","sc":1,"sum":"The Bank Secrecy Act’s $10,000 maximum penalty for the nonwillful failure to file a compliant report accrues on a per-report, not a per-account, basis.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"16"}},{"t":"case","label":"BP P.L.C. v. Mayor & City Council of Baltimore","cite":"141 S. Ct. 1532","y":2021,"id":"2020/19-1189","sc":1,"sum":"Where defendant energy companies premised 28 U. S. C. §1447(d) removal in part on the federal officer removal statute, §1442, the Fourth Circuit erred in holding that it lacked jurisdiction to consider all grounds for removal rejected by the District Court.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"19"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"4":"16"}},{"t":"case","label":"Gregg v. Georgia","cite":"428 U.S. 153","y":1976,"id":"1975/74-6257","sc":1,"op":1,"sum":"The Court ruled that the death penalty was not \"cruel and unusual\" punishment in violation of the Eighth and Fourteenth Amendments.","sumSrc":"Oyez","by":{"4":"14"}},{"t":"case","label":"INS v. Aguirre-Aguirre","cite":"526 U.S. 415","y":1999,"id":"1998/97-1754","sc":1,"sum":"The Court noted that withholding of deportation is mandatory if an alien establishes that it is more likely than not that he or she will suffer political persecution if deported.","sumSrc":"Oyez","by":{"4":"15"}},{"t":"case","label":"Ladner v. United States","cite":"358 U.S. 169","y":1958,"id":"1958/2","sc":1,"sum":"The single discharge of a shotgun alleged by petitioner in this case would constitute only a single violation of §254; petitioner is entitled to an opportunity to sustain his allegation that his conviction of two assaults rested upon evidence that the wounding of the two officers resulted from the single discharge of the gun; and the judgment is reversed and the cause remanded for further proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"22"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"4":"14"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"593 U.S. 155","y":2021,"id":"2020/19-863","sc":1,"op":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"4":"14"}},{"t":"case","label":"Ocasio v. United States","cite":"578 U.S. 282","y":2016,"id":"2015/14-361","sc":1,"sum":"The Court determined that a conspiracy to commit extortion can involve the purported victims of the extortion as members of the conspiracy.","sumSrc":"Oyez","by":{"4":"22"}},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"584 U.S. 357","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"4":"14"}},{"t":"case","label":"Scheidler v. Nat’l Org. for Women, Inc.","cite":"537 U.S. 393","y":2003,"id":"2002/01-1118","sc":1,"sum":"The Court held that abortion opponents did not commit extortion because they did not \"obtain\" property from the abortion supporters as required by the Hobbs Act. The Court further held that is first holding renders insufficient the other bases or predicate acts of racketeering supporting the jury's conclusion that the abortion opponents violated RICO.","sumSrc":"Oyez","by":{"4":"22"}},{"t":"case","label":"Torres v. Lynch","cite":"578 U.S. 452","y":2016,"id":"2015/14-1096","sc":1,"sum":"The Court determined that a state offense may constitute an aggravated felony for the purpose of the removal of a permanent resident when it includes all the elements of the federal statute with the exception of the interstate commerce element.","sumSrc":"Oyez","by":{"4":"15"}},{"t":"case","label":"United States v. Miller","cite":"891 F.3d 1220","y":2018,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/891/1220/","by":{"4":"8"}},{"t":"case","label":"United States v. Padilla","cite":"387 F.3d 1087","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/387/1087/","by":{"4":"6"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"4":"15"}},{"t":"law","label":"Pub. L. No. 115-123","url":"https://www.govinfo.gov/link/plaw/115/public/123","by":{"4":"15"}}]};